/* 
    Jaiza | CSS Design System
    Colors, Typography, Layout and Reset
*/

:root {
    /* Color Palette */
    --primary-dark: #0F2A2E; /* deep teal-charcoal */
    --bg-main: #F7F5F0;      /* warm paper white */
    --accent-gold: #C9A24B;  /* muted gold/brass */
    --secondary: #3D5C57;    /* sage-teal */
    --text-body: #1A1A1A;    /* near-black ink */
    --text-muted: #8B7355;   /* warm taupe */

    /* Typography */
    --font-display: 'Fraunces', serif;
    --font-body: 'Inter', sans-serif;
    --font-mono: 'IBM Plex Mono', monospace;

    /* Spacing */
    --space-sm: 0.5rem;
    --space-md: 1.5rem;
    --space-lg: 3rem;
    --space-xl: 6rem;

    /* Global Transitions */
    --transition-base: 0.3s ease-in-out;
}

/* Reset & Box Sizing */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

html {
    scroll-behavior: smooth;
    font-size: 16px;
}

body {
    background-color: var(--bg-main);
    color: var(--text-body);
    font-family: var(--font-body);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

/* Typography Base */
h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    font-weight: 400;
    line-height: 1.2;
    color: var(--primary-dark);
    margin-bottom: var(--space-md);
}

p {
    margin-bottom: var(--space-md);
    font-size: 1.125rem;
    max-width: 65ch;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color var(--transition-base);
}

a:focus-visible, button:focus-visible, input:focus-visible {
    outline: 2px solid var(--accent-gold);
    outline-offset: 4px;
}

/* Layout Utilities */
.container {
    width: 100%;
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 var(--space-md);
}

.section-padding {
    padding-top: var(--space-xl);
    padding-bottom: var(--space-xl);
}

.grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-xl);
    align-items: center;
}

@media (max-width: 768px) {
    .grid-2 {
        grid-template-columns: 1fr;
        gap: var(--space-lg);
    }
}

.bg-light {
    background-color: #FFFFFF;
}

.dark-section {
    background-color: var(--primary-dark);
    color: var(--bg-main);
}

.dark-section h1, .dark-section h2, .dark-section h3 {
    color: var(--bg-main);
}

.text-light-muted {
    color: #A0B2B4;
}

/* Common UI Elements */
.eyebrow-mono {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.875rem;
    letter-spacing: 0.05em;
    color: var(--text-muted);
    margin-bottom: var(--space-md);
    text-transform: uppercase;
}

.section-title {
    font-size: 2.5rem;
}

.btn {
    display: inline-block;
    padding: 0.875rem 1.75rem;
    font-family: var(--font-body);
    font-weight: 500;
    text-align: center;
    border-radius: 2px;
    cursor: pointer;
    border: 1px solid transparent;
    transition: all var(--transition-base);
}

.btn-primary {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
}

.btn-primary:hover {
    background-color: #b59242;
}

.btn-outline-light {
    border-color: rgba(247, 245, 240, 0.3);
    color: var(--bg-main);
}

.btn-outline-light:hover {
    border-color: var(--accent-gold);
    color: var(--accent-gold);
}

.btn-block {
    display: block;
    width: 100%;
}

/* Header */
.site-header {
    background-color: var(--primary-dark);
    color: var(--bg-main);
    position: sticky;
    top: 0;
    z-index: 100;
    padding: var(--space-sm) 0;
}

.header-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.brand-logo {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 600;
}

.main-nav ul {
    list-style: none;
    display: flex;
    gap: var(--space-md);
}

.main-nav a {
    font-size: 0.875rem;
    color: rgba(247, 245, 240, 0.8);
}

.main-nav a:hover {
    color: var(--accent-gold);
}

@media (max-width: 600px) {
    .main-nav {
        display: none; /* simple mobile fallback: hide nav, keep CTA */
    }
}

/* Hero Section */
.hero {
    padding: calc(var(--space-xl) * 1.5) 0 var(--space-xl);
}

.hero-container {
    display: grid;
    grid-template-columns: 3fr 2fr;
    gap: var(--space-xl);
    align-items: center;
}

.hero-title {
    font-size: clamp(2.5rem, 5vw, 4rem);
    margin-bottom: var(--space-md);
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--text-muted);
    margin-bottom: var(--space-lg);
}

.hero-visual {
    display: flex;
    justify-content: center;
}

.seal-icon {
    width: 100%;
    max-width: 320px;
    height: auto;
    opacity: 0.9;
}

@media (max-width: 900px) {
    .hero-container {
        grid-template-columns: 1fr;
    }
    .hero-visual {
        order: -1;
        margin-bottom: var(--space-lg);
    }
    .seal-icon {
        max-width: 200px;
    }
}

/* Problem Section */
.stat-card {
    border-top: 1px solid rgba(61, 92, 87, 0.2);
    padding-top: var(--space-md);
    margin-bottom: var(--space-md);
}

.stat-mono {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.875rem;
    color: var(--secondary);
    margin-bottom: 0.5rem;
}

.stat-card p {
    font-size: 1rem;
    color: var(--text-body);
}

/* Audit Process Section */
.process-steps {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: var(--space-lg);
    margin-top: var(--space-xl);
}

.step-card {
    position: relative;
    padding-top: var(--space-md);
    border-top: 2px solid var(--accent-gold);
}

.step-number {
    font-family: var(--font-mono);
    font-size: 1rem;
    color: var(--secondary);
    margin-bottom: var(--space-sm);
}

.step-title {
    font-size: 1.5rem;
    margin-bottom: var(--space-sm);
}

.step-card p {
    font-size: 1rem;
    color: var(--text-muted);
}

/* Deliverable Section */
.cert-reference {
    margin-top: var(--space-lg);
    padding: var(--space-sm) 0;
    border-top: 1px dashed var(--text-muted);
    border-bottom: 1px dashed var(--text-muted);
    display: inline-flex;
    gap: var(--space-md);
}

.mono-label {
    font-family: var(--font-mono);
    font-size: 0.875rem;
    color: var(--text-muted);
}

.mono-value {
    font-family: var(--font-mono);
    font-size: 0.875rem;
    color: var(--text-body);
    font-weight: 500;
}

.deliverable-visual {
    background-color: var(--bg-main);
    padding: var(--space-lg);
    border: 1px solid rgba(61, 92, 87, 0.1);
    position: relative;
    box-shadow: 0 4px 20px rgba(15, 42, 46, 0.05);
}

.seal-small {
    width: 100px;
    position: absolute;
    bottom: var(--space-lg);
    right: var(--space-lg);
}

.cert-mockup {
    opacity: 0.5;
}

.cert-line {
    height: 12px;
    background-color: rgba(61, 92, 87, 0.1);
    margin-bottom: var(--space-md);
    width: 100%;
}

.cert-line.head {
    height: 24px;
    width: 40%;
    margin-bottom: var(--space-lg);
}

.cert-line.short {
    width: 60%;
}

/* Trigger Section */
.trigger-container {
    max-width: 800px;
}

.trigger-container h2 {
    font-size: 3rem;
}

.trigger-container p {
    font-size: 1.25rem;
}

/* Contact Section */
.contact-container {
    max-width: 600px;
    margin: 0 auto;
}

.contact-form {
    margin-top: var(--space-lg);
    background-color: var(--bg-main);
    padding: var(--space-lg);
    border-radius: 2px;
    color: var(--text-body);
}

.form-group {
    margin-bottom: var(--space-md);
}

.form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-family: var(--font-mono);
    font-size: 0.875rem;
    color: var(--secondary);
}

.form-group input {
    width: 100%;
    padding: 0.75rem;
    border: 1px solid rgba(61, 92, 87, 0.3);
    border-radius: 2px;
    font-family: var(--font-body);
    font-size: 1rem;
    background-color: #FFFFFF;
}

.form-group input:focus {
    outline: 2px solid var(--accent-gold);
    border-color: transparent;
}

/* Footer */
.site-footer {
    background-color: var(--bg-main);
    padding: var(--space-lg) 0;
    border-top: 1px solid rgba(61, 92, 87, 0.1);
}

.footer-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.footer-brand {
    display: flex;
    flex-direction: column;
}

.footer-logo {
    font-family: var(--font-display);
    font-size: 1.25rem;
    color: var(--primary-dark);
}

.footer-tagline {
    font-size: 0.875rem;
    color: var(--text-muted);
}

.footer-contact a {
    font-family: var(--font-mono);
    font-size: 0.875rem;
    color: var(--secondary);
}

.footer-contact a:hover {
    color: var(--accent-gold);
}

@media (max-width: 600px) {
    .footer-container {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--space-md);
    }
}

/* Minimal Scroll Animation Support */
.fade-in {
    opacity: 0;
    transition: opacity 0.8s ease-out;
}

.fade-in-up {
    opacity: 0;
    transform: translateY(20px);
    transition: opacity 0.8s ease-out, transform 0.8s ease-out;
}

.visible {
    opacity: 1;
    transform: translateY(0);
}

/**
 * Jaiza | Minimal JavaScript Interactions
 */

document.addEventListener('DOMContentLoaded', () => {

    // Intersection Observer for scroll animations
    const observerOptions = {
        root: null,
        rootMargin: '0px',
        threshold: 0.15
    };

    const observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('visible');
                // Optional: Stop observing once visible if we only want it to animate once
                // observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Observe all elements with fade-in or fade-in-up classes
    const animatedElements = document.querySelectorAll('.fade-in, .fade-in-up');
    animatedElements.forEach(el => observer.observe(el));

    // Form submission handling (placeholder behavior)
    const form = document.querySelector('.contact-form');
    if (form) {
        form.addEventListener('submit', (e) => {
            // Because this is currently a placeholder Formspree endpoint, 
            // we let the native behavior handle it unless further requested.
            // A simple console log to verify interaction.
            console.log('Form submission intercepted. Point to active Formspree endpoint.');
        });
    }
});
